from decimal import Decimal


def record(log, kind, order_id, amount_cents):
    log.append({"kind": kind, "order_id": order_id, "amount_cents": amount_cents})


def upcast(event):
    """Return the event in the new shape (amount_cents); old events are converted."""
    if "amount_cents" in event:
        return dict(event)
    out = {k: v for k, v in event.items() if k != "amount"}
    out["amount_cents"] = int(Decimal(str(event["amount"])) * 100)
    return out

