"""Make customers.email unique, ignoring ASCII case.

Customers whose emails are equal after trimming surrounding spaces and ignoring ASCII case are one person. Keep the
one with the earliest created_at (the lowest id on a tie), move every order and address of the others to it, and
delete the others. If the kept customer's name is NULL or empty, give it the name of the earliest-created duplicate
that has one. Store every customer's email trimmed, with ASCII letters lowercased; other characters stay as they are.

Afterwards the customers table declares email as `email TEXT NOT NULL COLLATE NOCASE UNIQUE`. Everything else in the
schema stays as it is: the same tables and columns, the foreign keys with ON DELETE CASCADE, the index and the view.
Every order and address survives. conn comes from store.db.connect, with foreign keys on and no open transaction;
leave foreign keys on, commit your work, and set user_version to 2.
"""

import sqlite3

NEW_CUSTOMERS = """CREATE TABLE customers (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL COLLATE NOCASE UNIQUE,
    name TEXT,
    created_at TEXT NOT NULL
)"""

_ASCII_LOWER = str.maketrans("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz")


def _normalize(email):
    # Only U+0020 spaces are trimmed and only A-Z are lowercased; everything else is kept as is.
    return email.strip(" ").translate(_ASCII_LOWER)


def _by_creation(rows):
    # rows: (id, email, name, created_at, julianday). Compare instants when every created_at parses as a date,
    # so mixed ISO spellings ('T' vs ' ', time zones) order correctly; otherwise fall back to the raw text.
    if all(row[4] is not None for row in rows):
        return sorted(rows, key=lambda row: (row[4], row[0]))
    return sorted(rows, key=lambda row: (row[3], row[0]))


def _merge(conn):
    rows = conn.execute("SELECT id, email, name, created_at, julianday(created_at) FROM customers").fetchall()
    groups = {}
    for row in rows:
        groups.setdefault(_normalize(row[1]), []).append(row)

    customers = []
    moves = []
    for email, group in groups.items():
        kept, *others = _by_creation(group)
        cid, _, name, created_at, _ = kept
        if name is None or name == "":
            for other in others:
                if other[2] is not None and other[2] != "":
                    name = other[2]
                    break
        customers.append((cid, email, name, created_at))
        moves.extend((cid, other[0]) for other in others)

    conn.executemany("UPDATE orders SET customer_id = ? WHERE customer_id = ?", moves)
    conn.executemany("UPDATE addresses SET customer_id = ? WHERE customer_id = ?", moves)
    return customers


def _rebuild(conn, customers):
    # SQLite cannot change a column's constraints in place, so recreate the table under its own name. Dropping and
    # recreating (instead of renaming a copy) keeps the view and the other tables' foreign keys untouched.
    dependents = [
        sql
        for (sql,) in conn.execute(
            "SELECT sql FROM sqlite_master WHERE tbl_name = 'customers' AND type IN ('index', 'trigger') "
            "AND sql IS NOT NULL ORDER BY rowid"
        )
    ]
    conn.execute("DROP TABLE customers")
    conn.execute(NEW_CUSTOMERS)
    conn.executemany("INSERT INTO customers (id, email, name, created_at) VALUES (?, ?, ?, ?)", customers)
    for sql in dependents:
        conn.execute(sql)


def upgrade(conn):
    conn.execute("PRAGMA foreign_keys = OFF")
    try:
        if conn.execute("PRAGMA foreign_keys").fetchone()[0]:
            raise RuntimeError("could not turn foreign keys off; is a transaction open?")
        conn.execute("BEGIN")
        try:
            _rebuild(conn, _merge(conn))
            if conn.execute("PRAGMA foreign_key_check").fetchone() is not None:
                raise sqlite3.IntegrityError("foreign key check failed after merging customers")
            conn.execute("PRAGMA user_version = 2")
            conn.commit()
        except BaseException:
            conn.rollback()
            raise
    finally:
        conn.execute("PRAGMA foreign_keys = ON")

