leave foreign keys on, commit your work, and set user_version to 2.
"""

NEW_CUSTOMERS = """CREATE TABLE customers (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL COLLATE NOCASE UNIQUE,
    name TEXT,
    created_at TEXT NOT NULL
)"""

# Map only ASCII A-Z to a-z; every other character is left untouched.
_ASCII_LOWER = {c: c + 32 for c in range(ord("A"), ord("Z") + 1)}


def _normalize_email(email):
    # Trim surrounding spaces (U+0020 only, like SQLite's trim()) and lowercase ASCII letters only.
    return email.strip(" ").translate(_ASCII_LOWER)


def _age_key(row):
    """Sort key: earliest created_at first, lowest id on a tie.

    created_at is compared as a point in time via SQLite's julianday(), so values that differ only in format
    (e.g. 'T' vs ' ' separator, or a timezone offset) compare correctly. Values julianday() cannot parse sort
    after all parseable ones, ordered by their text.
    """
    cid, _email, _name, created_at, jd = row
    if jd is not None:
        return (0, jd, "", cid)
    return (1, 0.0, created_at, cid)


def _has_name(name):
    return name is not None and name != ""


def _referencing_columns(conn):
    """(table, column) pairs holding a foreign key to customers.id, in any table."""
    refs = []
    tables = [r[0] for r in conn.execute(
        "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name != 'customers'"
    )]
    for table in tables:
        for fk in conn.execute("SELECT \"table\", \"from\", \"to\" FROM pragma_foreign_key_list(?)", (table,)):
            target, src, dst = fk
            if target.lower() == "customers" and (dst is None or dst.lower() == "id"):
                refs.append((table, src))
    return refs


def _quote(ident):
    return '"' + ident.replace('"', '""') + '"'


def upgrade(conn):
    # Rebuilding customers requires dropping it, which with foreign keys on would cascade-delete every order and
    # address. foreign_keys cannot change inside a transaction, so switch it off first and always restore it.
    conn.execute("PRAGMA foreign_keys = OFF")
    try:
        conn.execute("BEGIN IMMEDIATE")
        try:
            _migrate(conn)
            conn.commit()
        except BaseException:
            conn.rollback()
            raise
    finally:
        conn.execute("PRAGMA foreign_keys = ON")


def _migrate(conn):
    rows = conn.execute(
        "SELECT id, email, name, created_at, julianday(created_at) FROM customers"
    ).fetchall()

    groups = {}
    for row in rows:
        groups.setdefault(_normalize_email(row[1]), []).append(row)

    survivors = []  # (id, email, name, created_at)
    repoint = []  # (survivor_id, loser_id)
    for email, members in groups.items():
        members.sort(key=_age_key)
        keep = members[0]
        name = keep[2]
        if not _has_name(name):
            for other in members[1:]:
                if _has_name(other[2]):
                    name = other[2]
                    break
        survivors.append((keep[0], email, name, keep[3]))
        repoint.extend((keep[0], other[0]) for other in members[1:])

    # Move every referencing row (orders, addresses, and any other FK to customers) to the surviving customer.
    for table, column in _referencing_columns(conn):
        conn.executemany(
            f"UPDATE {_quote(table)} SET {_quote(column)} = ? WHERE {_quote(column)} = ?",
            repoint,
        )

    # Keep the definitions of indexes and triggers attached to customers so they can be recreated after the
    # rebuild (the view and indexes on other tables are untouched by dropping and recreating customers).
    attached = [r[0] for r in conn.execute(
        "SELECT sql FROM sqlite_master WHERE tbl_name = 'customers' AND type IN ('index', 'trigger') "
        "AND sql IS NOT NULL ORDER BY type = 'trigger', rowid"
    )]

    conn.execute("DROP TABLE customers")
    conn.execute(NEW_CUSTOMERS)
    conn.executemany(
        "INSERT INTO customers (id, email, name, created_at) VALUES (?, ?, ?, ?)",
        sorted(survivors),
    )
    for sql in attached:
        conn.execute(sql)

    problems = conn.execute("PRAGMA foreign_key_check").fetchall()
    if problems:
        raise RuntimeError(f"foreign key violations after merging customers: {problems!r}")

    conn.execute("PRAGMA user_version = 2")

